const token=prompt('Enter the admin token'),auth={Authorization:'Bearer '+token,'Content-Type':'application/json'},$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function req(u,b){const r=await fetch(u,{method:b?'POST':'GET',headers:auth,body:b?JSON.stringify(b):undefined}),d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}function heat(e,options,assign){return `<div class="event-row tree-heat"><div><h3>${esc(e.stage||e.name)}</h3><p>${esc(e.name)} · ${e.count} results</p></div>${assign?`<select data-heat="${esc(e.id)}"><option value="">Assign to tournament…</option>${options}</select><button class="btn assign" data-id="${esc(e.id)}">Assign</button>`:''}</div>`}async function render(){try{const d=await req('/api/admin/status'),p=d.meta.feed_paused==='true',f=d.file;$('#export-dir').value='RACE_EXPORT_DIR='+d.sourceConfig.hostDirectory;$('#export-filename').value='RACE_EXPORT_FILENAME='+d.sourceConfig.filename;$('#app-version').textContent='Version '+d.version;$('#file-status').textContent=f.exists?`Reading ${f.configured} · ${f.bytes} bytes`:`Waiting for ${f.configured}`;$('#import-status').textContent=d.meta.last_error?'Last error: '+d.meta.last_error:'Last successful import: '+(d.meta.last_import||'waiting');$('#event-status').value=d.meta.status||'Live';$('#event-status').onchange=()=>req('/api/admin/status',{status:$('#event-status').value});$('#feed-toggle').textContent=p?'Start live updates':'Stop live updates ('+d.pollSeconds+'s)';$('#feed-toggle').onclick=async()=>{await req('/api/admin/feed',{running:p});render()};const known=d.tournaments.map(t=>t.name),opts=d.tournaments.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');const grouped=d.tournaments.map(t=>({t,heats:d.events.filter(e=>e.tournament===t.name)}));const unassigned=d.events.filter(e=>!known.includes(e.tournament));$('#event-list').innerHTML=`<div class="tree-toolbar"><input id="new-tournament" placeholder="New tournament name"><button class="btn yellow" id="add-tournament">Create tournament</button></div><div class="tree">${grouped.map(g=>`<section class="tree-node"><h2>⌄ ${esc(g.t.name)}</h2><div class="tree-children">${g.heats.length?g.heats.map(e=>heat(e,'',false)).join(''):'<p>No heats assigned yet.</p>'}</div></section>`).join('')}<section class="tree-node unassigned"><h2>⌄ Unassigned heats</h2><div class="tree-children">${unassigned.length?unassigned.map(e=>heat(e,opts,true)).join(''):'<p>All imported heats are assigned.</p>'}</div></section></div>`;$('#add-tournament').onclick=async()=>{const name=$('#new-tournament').value.trim();if(name){await req('/api/admin/tournaments',{name});render()}};$('#event-list').querySelectorAll('.assign').forEach(b=>b.onclick=async()=>{const id=b.dataset.id,sel=$('#event-list').querySelector('[data-heat="'+CSS.escape(id)+'"]'),t=d.tournaments.find(x=>x.id===+sel.value),e=d.events.find(x=>x.id===id);if(!t)return;await req('/api/admin/events/'+encodeURIComponent(id),{mapping:true,tournament:t.name,stage:e.stage||e.name,name:e.name});render()})}catch(e){$('#event-list').textContent=e.message}}render();

